    position: "fixed", right: "14px", bottom: "14px", zIndex: "2147483647",
    padding: "6px", border: "1px solid rgba(148,163,184,.45)", borderRadius: "10px",
    background: "rgba(255,255,255,.94)", boxShadow: "0 8px 28px rgba(15,23,42,.16)",
